import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-039 — Home: a two-column hero puts the intro in the first screen, one glyph component draws every route card (Lab added), the cards heading counts itself, the body text uses the shell tokens","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-039-home-two-column-hero-one-glyph-component-and-type-scale.md","filePath":"uxs/decisions/UXD-039-home-two-column-hero-one-glyph-component-and-type-scale.md"}'),n={name:"uxs/decisions/UXD-039-home-two-column-hero-one-glyph-component-and-type-scale.md"};function d(r,e,h,i,c,l){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-039-—-home-a-two-column-hero-puts-the-intro-in-the-first-screen-one-glyph-component-draws-every-route-card-lab-added-the-cards-heading-counts-itself-the-body-text-uses-the-shell-tokens" tabindex="-1">UXD-039 — Home: a two-column hero puts the intro in the first screen, one glyph component draws every route card (Lab added), the cards heading counts itself, the body text uses the shell tokens <a class="header-anchor" href="#uxd-039-—-home-a-two-column-hero-puts-the-intro-in-the-first-screen-one-glyph-component-draws-every-route-card-lab-added-the-cards-heading-counts-itself-the-body-text-uses-the-shell-tokens" aria-label="Permalink to &quot;UXD-039 — Home: a two-column hero puts the intro in the first screen, one glyph component draws every route card (Lab added), the cards heading counts itself, the body text uses the shell tokens&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; checked by unit tests, e2e on three projects and screenshots, not yet by the operator)</li><li><strong>Date</strong>: 2026-11-14 (proposed and decided)</li><li><strong>Decider</strong>: the operator, 2026-11-14 — the recommendations of <code>docs/wip/2026-11-14-slice-F3-brief.md</code> §12 approved as written (&quot;I&#39;m okay with all the recommendations. Go for them.&quot;: decisions 33a, 34a, 35a, 36a, 37a, 38a, 39a, 40a, 41a); &quot;don&#39;t touch heroes ... what we have now is good&quot; (2026-11-14)</li><li><strong>Answers</strong>: H1, H2, H3, H4, H5, H6, H7, H8 of the UX feedback plan; D1, D2, D3; L3 (kept); slice F3</li><li><strong>Builds on</strong>: <a href="./UXD-003-home-route-card-titles-upright">UXD-003</a> (card titles stay upright Space Mono), <a href="./UXD-012-one-page-shell">UXD-012</a> (the home page stays off the shell), <a href="./UXD-027-explore-levels-one-table-glyphs-card-and-hint">UXD-027</a> (the eight level glyphs are <code>ScaleGlyph</code>&#39;s)</li><li><strong>Changes</strong>: <code>src/routes/+page.svelte</code>, <code>src/lib/components/RouteGlyph.svelte</code>, <code>RouteGlyphDefs.svelte</code>, <code>RouteGlyph.test.ts</code> (new), <code>src/lib/components/RouteCardGrid.svelte</code>, <code>landing_section_cards_heading</code> in the 14 locale files, <code>scripts/i18n-tools/en-source-hashes.json</code>, <code>tests/e2e/landing-first-screen.spec.ts</code> and <code>landing-tv.spec.ts</code> (new), <code>tests/e2e/landing.spec.ts</code>. No file under <code>static/images/</code> or <code>static/data/</code> changed.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><strong>H1.</strong> &quot;Opening image is too big; one must scroll to reach the basic intro.&quot; The hero picture was 760 x 510 px on a laptop, so the first intro heading was at y 1023 at 1440x900 and at 1366x768, and the fixed footer strip covered the second CTA (900 px) or every CTA (768 px). <strong>H2.</strong> The Lab was in the nav&#39;s Learn group and on <code>/learn</code>, but not on the home grid, and no glyph drew it on either page: the home page and <code>RouteCardGrid</code> each held their own copy of the icon chain (about 535 lines). <strong>Cards heading.</strong> <code>landing_section_cards_heading</code> said &quot;All 12 destinations&quot; in 14 locales; the grid had 22 cards. <strong>H8.</strong> The home page had five body sizes (12, 13, 14, 15, 17 px) against the shell&#39;s 14 and 11.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>A consistency pass, no redesign (33a; D1).</strong> The section order, the three CTAs and the card grid stay. A redesign has no mock-up behind it; the pass is the base it would need.</li><li><strong>Two columns from 1024 px (34a; H1, H3).</strong> <code>.hero</code> becomes a grid: the wordmark, tagline, subhead and the three CTAs (<code>.hero-copy</code>, left) and the same picture (right, <code>min(400px, 30vw)</code> wide). At 1366x768 the wordmark is at y 76, the CTAs at y 332 to 506, the &quot;What is this?&quot; heading at y 587 to 626, the footer strip&#39;s top at 732; at 1440x900 the same, the strip at 864. The divider margin is 40 px from 768 up (it was 64). Below 1024 px and on phones the hero is the stack it was (picture, wordmark, tagline, subhead, CTAs; 390x844 shows all three CTAs and the heading). In RTL the copy is on the right of the picture. Amended 2026-11-14 (operator, after the screenshots: &quot;let image go behind the text on the left side ... maximize graphical impact&quot;, then &quot;Bigger home is ok&quot;): the picture is <code>min(800px, 56vw)</code>, right-aligned, breaking out of the 880 px column toward the window edge by up to 260 px, and runs behind the copy, whose side of it fades out (mask transparent to opaque over the first 42%, other edges 18%); the copy has a soft dark text-shadow. In RTL the fade flips; the picture is never mirrored. At 1366x768 the picture is 765 px wide (56vw) so the &quot;What is this?&quot; heading clears the fixed footer strip (at 60vw it ended 1 px under the strip; <code>landing-first-screen.spec.ts</code> caught it). The picture file is untouched: same <code>app-landing-hero.webp</code>, only its box and mask changed (nothing under <code>static/images/</code>; no hero slot or override).</li><li><strong>The hero stays a still (39a; D2) and nothing is added for &quot;engaging&quot; (38a; H3, H5, H6).</strong> H3 is read as the result of H1; no live line, no mini orrery, no video, no Higgsfield run.</li><li><strong>The teal arc in the hero picture stays (35a; L3).</strong> The arc is part of the picture the operator keeps; the file is not edited. L3 closes as &quot;kept&quot;.</li><li><strong>One glyph component (36a; H2).</strong> <code>RouteGlyph</code> draws every route-card icon (SVG children, keyed by glyph id; the Explore level glyphs go to <code>ScaleGlyph</code>); <code>RouteGlyphDefs</code> is the one <code>&lt;defs&gt;</code> block (the 16 <code>ic-*</code> gradients). The home grid and <code>RouteCardGrid</code> (the section hubs: <code>/learn</code>, <code>/worlds</code>, <code>/catalog</code>, <code>/explore/hub</code>) both use them; the 535-line copies are gone. The Lab glyph is new (a notebook page with a grid, a dashed throw parabola ending in a gold marker and a thrust arrow; accent blue and gold, no teal or cyan). The Lab card is the first card under LEARN on the home grid (Lab, Essays, Science, the nav&#39;s order), with the keys that already existed in 14 locales. The home grid now has 23 cards under 5 headings.</li><li><strong>Four glyphs have two drawings (an open point).</strong> The two old copies were not the same for earth (the hub draws a second continent stroke), programs (home: a flag-pole of agency dots; hub: a mission patch), live (home: a dish; hub: a signal dot with arcs) and essays (home: a bookmarked book; hub: a book with a star). The brief asked for &quot;the same icon on home and /learn&quot;, the build rule was that every existing glyph renders as before, so <code>RouteGlyph</code> has a <code>variant</code> prop (<code>&#39;home&#39;</code>, the default, and <code>&#39;hub&#39;</code>, which <code>RouteCardGrid</code> passes) and keeps both drawings; the other ten glyphs are one drawing. Making each of the four one drawing is a one-line choice per glyph, left to the operator. Venus had no hub drawing: the Worlds hub&#39;s Venus card now draws the home glyph.</li><li><strong>The cards heading counts itself (37a).</strong> <code>landing_section_cards_heading</code> is &quot;All {count} destinations&quot; (14 locales; the number only through <code>{count}</code>), the count the number of cards the grid renders (23). Russian is &quot;Все пункты назначения: {count}&quot;, because the plural form of &quot;пункт&quot; follows the number (12 is &quot;пунктов&quot;, 23 is &quot;пункта&quot;) and a computed count cannot be inflected.</li><li><strong>Body text on the shell tokens (41a; H8).</strong> Five body sizes become two: <code>--size-body</code> (14 px: subhead, prose) and <code>--size-lead</code> (16 px: the &quot;What is this?&quot; first paragraph and the card titles), plus <code>--size-meta</code> (12 px: card descriptions, the About block). The Bebas display sizes (wordmark 48/80/96, h2 24/32, the card route names 22, the grid headings 13, the CTA labels 14) stay home-specific; card titles stay upright Space Mono (UXD-003). The home page stays off the shell (UXD-012).</li><li><strong>The TV layout stays two panels (40a; D3, H4), now with a spec, and one defect fixed.</strong> The first emulation (1920x1080, coarse pointer, no hover, 1 dppx) found the route grid&#39;s heading and first card rows above the top of the page (its box started at y -490) (a fixed <code>100svh</code> row with the grid centred in it, the grid 2,228 px tall). The row is now <code>minmax(100svh, auto)</code> with items aligned to the start, and the hero is <code>position: sticky</code>, <code>100svh</code> high and centred, so the heading and the first row of cards are in the first screen and the hero stays while the cards scroll. The hero is one centred column again inside its half. What the TV app needs beyond the home page is a separate brief the operator scopes.</li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Unit: <code>RouteGlyph.test.ts</code> (every glyph id the home grid names is drawn, the Lab is in the map, the hub and home variants differ only for earth, programs, live and essays). Before = after: the 14 home-chain and 13 hub-chain branches compared with the HEAD markup (27 of 27 equal), and a pixel comparison on the running pages that swaps the old markup into each icon and screenshots both (25 of 25 byte-identical PNGs on home, <code>/learn</code>, <code>/worlds</code>, <code>/catalog</code>; the eight level glyphs are <code>ScaleGlyph</code>&#39;s, unchanged). E2E on desktop, mobile and mobile-landscape against the dev server: <code>landing-first-screen.spec.ts</code> (the wordmark, the CTAs and the heading inside the viewport and not under the footer strip at 1366x768 and 1440x900, an <code>elementFromPoint</code> check, the phone, <code>de</code> and <code>ar</code>, the Lab card first under LEARN, <code>/learn</code> and home draw the same Lab glyph, the heading shows the grid&#39;s count in en and de), <code>landing-tv.spec.ts</code>, <code>landing.spec.ts</code>, <code>a11y.spec.ts</code> (home and <code>/learn</code>, 0 violations), <code>footer-dock.spec.ts</code> (home). Screenshots read: home at 1366x768, 1440x900 and 390x844 before and after, <code>de</code>, <code>ar</code>, the TV, the Learn section, <code>/learn</code>.</p><p>Not checked: Safari and iOS (the <code>var()</code> and <code>color-mix()</code> SVG check is L8), a real TV, the 14 locales&#39; first screens other than <code>de</code> and <code>ar</code>, the 13 non-English curator tour transcripts for a spoken card count (the en-US ones were searched for &quot;destinations&quot;, &quot;twelve&quot; and &quot;12 cards&quot; and none refers to the home grid; narration cannot be re-recorded in this slice). The tour&#39;s cue sequence flashes cards by stage id and does not flash the Lab.</p>',9)])])}const g=o(n,[["render",d]]);export{u as __pageData,g as default};
